void Solver::bump_var(int var, double coeff) {
    // increase activity of the variable
    activity[var] += var_inc * coeff;

    // prevent activity overflow by rescaling all activities and var_inc
    const double MAX_ACTIVITY = 1e150;
    if (activity[var] > MAX_ACTIVITY) {
        double scale = 1e-150;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // keep the VSIDS heap consistent
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
